        // Measure gas without exclusions
        uint256 gasBefore = gasleft();
        token.balanceOf(owner);
        uint256 initialGasUsed = gasBefore - gasleft();

        // Exclude 300 accounts
        for (uint256 i = 0; i < 300; i++) {
            address account = address(uint160(0x1000 + i));
            token.excludeAccount(account);
        }

        // Measure gas with 300 exclusions
        uint256 gasAfter = gasleft();
        token.balanceOf(owner);
        uint256 finalGasUsed = gasAfter - gasleft();

        // Log gas metrics
        emit log_named_uint("Gas used without exclusions", initialGasUsed);
        emit log_named_uint("Gas used with 300 exclusions", finalGasUsed);

        // Verify significant gas cost increase
        assertGt(finalGasUsed, initialGasUsed * 2, "Gas consumption did not increase as expected");
